-- Varukatalogen från supabase/katalog/varor/brod.csv, supabase/katalog/varor/drycker.csv, supabase/katalog/varor/frukost.csv, supabase/katalog/varor/glutenfritt.csv, supabase/katalog/varor/korv_chark.csv, supabase/katalog/varor/mellanmal.csv, supabase/katalog/varor/ost_mejeri.csv, supabase/katalog/varor/snabbmat.csv, supabase/katalog/varor/tuber_smaksattning.csv.
-- Skapad med "npm run varukatalog". Ändra inte filen för hand: ändra CSV:n och skapa en ny migrering.

on conflict (lower(marke), lower(namn)) do update set
  marke = excluded.marke,
  namn = excluded.namn,
  kategori = excluded.kategori,
  forpackning_g = excluded.forpackning_g,
  portion_g = excluded.portion_g,
  kcal_per_100g = excluded.kcal_per_100g,
  protein_per_100g = excluded.protein_per_100g,
  fett_per_100g = excluded.fett_per_100g,
  kolhydrater_per_100g = excluded.kolhydrater_per_100g,
  fiber_per_100g = excluded.fiber_per_100g,
  socker_per_100g = excluded.socker_per_100g,
  salt_per_100g = excluded.salt_per_100g,
  vatten_ml = excluded.vatten_ml,
  tillagning = excluded.tillagning,
  vegetarisk = excluded.vegetarisk,
  vegansk = excluded.vegansk,
  glutenfri = excluded.glutenfri,
  laktosfri = excluded.laktosfri,
  allergener = excluded.allergener,
  spar = excluded.spar,
  haller_utan_kyl = excluded.haller_utan_kyl,
  ean = excluded.ean,
  pris_sek_ca = excluded.pris_sek_ca,
  pris_kalla = excluded.pris_kalla,
  kalla = excluded.kalla;
